import html, subprocess, pathlib
W,H=1200,1700
def crop(img,x,y,w,h,dw,dh=None,cls=''):
    dh=dh or round(dw*h/w); s=dw/w
    return (f'<div class="crop {cls}" style="width:{dw}px;height:{dh}px"><img src="src/{img}.jpg" '
            f'style="width:{960*s:.1f}px;left:{-x*s:.1f}px;top:{-y*s:.1f}px"></div>')
CSS='''
@page{size:1200px 1700px;margin:0}
*{box-sizing:border-box;margin:0}
body{width:1200px;height:1700px;font-family:"DejaVu Sans",Arial,sans-serif;color:#fff;
 background:linear-gradient(180deg,#0b1a3a 0%,#173a78 55%,#0b1a3a 100%);position:relative;overflow:hidden}
.crop{overflow:hidden;position:relative;flex:none;border:4px solid #d9b45a;border-radius:6px}
.crop img{position:absolute}
.star{color:#d9b45a;font-size:46px;text-align:center}
h1{font-size:92px;letter-spacing:2px;text-align:center;line-height:1.02;font-weight:800}
.bar{height:6px;background:linear-gradient(90deg,#fff 33%,#1c57a5 33% 66%,#d52b1e 66%);margin:0 60px}
.head{padding:28px 60px 16px;text-align:center}
.head h1{font-size:62px}
.rows{padding:20px 60px;display:flex;flex-direction:column;gap:22px}
.row{display:flex;gap:30px;background:rgba(255,255,255,.95);color:#111;border-radius:10px;padding:18px;align-items:flex-start}
.row.r{flex-direction:row-reverse}
.row h2{font-size:30px;color:#12306b;margin-bottom:6px}
.row .sub{font-size:16px;color:#7a5b10;font-weight:700;margin-bottom:8px}
.row p{font-size:15.3px;line-height:1.34;text-align:justify}
.row h3{font-size:18px;color:#12306b;margin:6px 0 3px}
.foot{position:absolute;bottom:18px;width:100%;text-align:center;font-size:14px;opacity:.7}
'''
def page(body,name):
    p=pathlib.Path(f'{name}.html'); p.write_text(f'<!doctype html><meta charset=utf-8><style>{CSS}</style>{body}')
    subprocess.run(['/opt/pw-browsers/chromium','--headless','--no-sandbox','--disable-gpu','--hide-scrollbars',
      f'--window-size={W},{H+87}',f'--screenshot={name}.png',f'file://{p.resolve()}'],check=True,capture_output=True)
def hero(img,box,name,sub,paras,rev=False,pw=270):
    ps=''.join(f'<p>{html.escape(t)}</p>' if not t.startswith('#') else f'<h3>{html.escape(t[1:])}</h3>' for t in paras)
    return (f'<div class="row {"r" if rev else ""}">{crop(img,*box,pw,pw*4//3 if False else None)}'
            f'<div><h2>{html.escape(name)}</h2><div class="sub">{html.escape(sub)}</div>{ps}</div></div>')
def heroes(n,items):
    return (f'<div class="head"><div class="star">★</div><h1>ГЕРОИ СПЕЦОПЕРАЦИИ</h1></div><div class="bar"></div>'
            f'<div class="rows">{"".join(items)}</div><div class="foot">Плакат {n} из 5</div>')

